#### Variation 1: Webhook-Based Integration (Push Model)

**Scenario**: Real-time integration where partner needs immediate event notification

**Implementation**:

```csharp
// Webhook delivery service
public class WebhookDeliveryService
{
    private readonly IPartnerRegistry _partners;
    private readonly IHttpClientFactory _httpFactory;
    private readonly IDeadLetterQueue _dlq;

    public async Task DeliverEventAsync(ExternalEvent evt, Partner partner)
    {
        var webhookConfig = partner.WebhookConfiguration;
        var client = _httpFactory.CreateClient("webhook-delivery");

        // Configure authentication
        var request = new HttpRequestMessage(HttpMethod.Post, webhookConfig.Url);
        request.Headers.Add("X-Event-Type", evt.EventType);
        request.Headers.Add("X-Event-Id", evt.EventId);

        if (webhookConfig.AuthType == "ApiKey")
        {
            request.Headers.Add("X-API-Key", webhookConfig.ApiKey);
        }
        else if (webhookConfig.AuthType == "OAuth")
        {
            var token = await GetOAuthTokenAsync(webhookConfig);
            request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", token);
        }

        // Add event payload
        request.Content = JsonContent.Create(evt.Payload);

        // Retry policy: exponential backoff, 5 attempts
        var retryPolicy = Policy
            .HandleResult<HttpResponseMessage>(r => !r.IsSuccessStatusCode)
            .Or<HttpRequestException>()
            .WaitAndRetryAsync(
                retryCount: 5,
                sleepDurationProvider: attempt => TimeSpan.FromSeconds(Math.Pow(2, attempt)),
                onRetry: (result, timespan, attempt, context) =>
                {
                    _logger.LogWarning(
                        "Webhook delivery attempt {Attempt} failed for partner {Partner}. Retrying in {Delay}s",
                        attempt, partner.Id, timespan.TotalSeconds);
                });

        try
        {
            var response = await retryPolicy.ExecuteAsync(async () =>
            {
                return await client.SendAsync(request);
            });

            if (response.IsSuccessStatusCode)
            {
                await LogDeliverySuccessAsync(evt.EventId, partner.Id);
            }
            else
            {
                // Exhausted retries - move to DLQ
                await _dlq.EnqueueAsync(new DeadLetter
                {
                    EventId = evt.EventId,
                    PartnerId = partner.Id,
                    Reason = $"HTTP {response.StatusCode}: {await response.Content.ReadAsStringAsync()}",
                    Payload = evt
                });
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Fatal error delivering webhook to {Partner}", partner.Id);
            await _dlq.EnqueueAsync(new DeadLetter
            {
                EventId = evt.EventId,
                PartnerId = partner.Id,
                Reason = ex.Message,
                Payload = evt
            });
        }
    }
}
```

**When to Use**: Partners need real-time notifications; partners can host webhook endpoints; low latency required

**Trade-offs**:
- **Pros**: Real-time delivery; simple for partners (just HTTP endpoint); push-based eliminates polling
- **Cons**: Partners must maintain availability; firewall configuration; webhook endpoint security concerns

