#### Variation 2: File-Based Integration (Pull Model)

**Scenario**: Batch integration where partner polls for files on schedule

**Implementation**:

```csharp
// File-based integration service
public class FileBasedIntegrationService
{
    private readonly IBlobStorage _storage;
    private readonly IPartnerRegistry _partners;

    public async Task GeneratePartnerFileAsync(string partnerId, IEnumerable<ExternalEvent> events)
    {
        var partner = await _partners.GetAsync(partnerId);
        var fileConfig = partner.FileConfiguration;

        // Generate file in partner-specific format
        var fileContent = fileConfig.Format switch
        {
            "CSV" => GenerateCsvFile(events, fileConfig.CsvMapping),
            "XML" => GenerateXmlFile(events, fileConfig.XmlSchema),
            "JSON" => GenerateJsonFile(events),
            "EDI" => GenerateEdiFile(events, fileConfig.EdiVersion),
            _ => throw new NotSupportedException($"Format {fileConfig.Format} not supported")
        };

        // Generate filename with timestamp
        var filename = $"{fileConfig.FilePrefix}_{DateTime.UtcNow:yyyyMMddHHmmss}.{fileConfig.Extension}";
        var filePath = $"{partnerId}/outbound/{filename}";

        // Upload to partner's SFTP directory or blob container
        await _storage.UploadAsync(filePath, fileContent);

        // Generate companion control file if required
        if (fileConfig.RequiresControlFile)
        {
            var controlFile = GenerateControlFile(filename, events.Count(), fileContent.Length);
            await _storage.UploadAsync($"{filePath}.ctl", controlFile);
        }

        _logger.LogInformation(
            "Generated file {Filename} for partner {Partner} with {EventCount} events",
            filename, partnerId, events.Count());
    }

    // Schedule: run every hour to batch events into files
    [CronJob("0 * * * *")]  // Top of every hour
    public async Task GenerateScheduledFilesAsync()
    {
        var partners = await _partners.GetAllWithFileIntegrationAsync();

        foreach (var partner in partners)
        {
            // Get events accumulated since last file generation
            var events = await GetPendingEventsForPartnerAsync(partner.Id);

            if (events.Any())
            {
                await GeneratePartnerFileAsync(partner.Id, events);
                await MarkEventsAsDeliveredAsync(events);
            }
        }
    }
}
```

**When to Use**: Partners prefer batch processing; partners have legacy systems; state contracts mandate file-based exchange

**Trade-offs**:
- **Pros**: Works with legacy systems; partners control polling schedule; simpler partner infrastructure
- **Cons**: Higher latency (polling interval); file generation overhead; storage costs

