#### Variation 3: Event Store with API Polling

**Scenario**: Partner polls API endpoint for new events instead of receiving pushes

**Implementation**:

```csharp
[ApiController]
[Route("api/integration/events")]
public class PartnerEventApiController : ControllerBase
{
    private readonly IPartnerEventStore _eventStore;
    private readonly IPartnerRegistry _partners;

    // Partner polls this endpoint for new events
    [HttpGet]
    [Authorize(Policy = "PartnerApiAccess")]
    public async Task<IActionResult> GetEventsAsync(
        [FromQuery] string since = null,
        [FromQuery] int maxResults = 100,
        [FromQuery] string eventType = null)
    {
        var partnerId = User.FindFirst("partner_id")?.Value;

        // Parse since timestamp (last event partner processed)
        var sinceTimestamp = string.IsNullOrEmpty(since)
            ? DateTime.UtcNow.AddHours(-24)  // Default: last 24 hours
            : DateTime.Parse(since);

        // Retrieve events for this partner
        var events = await _eventStore.GetEventsAsync(new EventQuery
        {
            PartnerId = partnerId,
            Since = sinceTimestamp,
            EventType = eventType,
            MaxResults = Math.Min(maxResults, 1000)  // Cap at 1000
        });

        // Return events with pagination metadata
        return Ok(new
        {
            events = events.Select(e => new
            {
                eventId = e.EventId,
                eventType = e.EventType,
                occurredAt = e.OccurredAt,
                data = e.Payload
            }),
            pagination = new
            {
                count = events.Count,
                nextSince = events.Any() ? events.Max(e => e.OccurredAt).ToString("o") : null,
                hasMore = events.Count == maxResults
            }
        });
    }

    // Partner acknowledges processing events
    [HttpPost("acknowledge")]
    [Authorize(Policy = "PartnerApiAccess")]
    public async Task<IActionResult> AcknowledgeEventsAsync(
        [FromBody] EventAcknowledgment ack)
    {
        var partnerId = User.FindFirst("partner_id")?.Value;

        await _eventStore.MarkAcknowledgedAsync(partnerId, ack.EventIds);

        return NoContent();
    }
}
```

**When to Use**: Partners prefer pull model; partners behind firewall can't receive webhooks; partners need to control consumption rate

**Trade-offs**:
- **Pros**: Partner controls polling frequency; no webhook infrastructure needed; works behind firewalls
- **Cons**: Higher latency; inefficient if polling returns no events; API rate limiting needed

