#### Phase 1: Foundation (Weeks 1-4)

**Goal**: Establish core event infrastructure and first protocol adapter

**Activities**:

1. **Deploy Event Broker**:
   ```bash
   # Example: Azure Event Hubs namespace creation
   az eventhubs namespace create \
     --name gainwell-integration-prod \
     --resource-group integration-rg \
     --location eastus \
     --sku Standard \
     --capacity 2

   # Create topics for different domains
   az eventhubs eventhub create \
     --name claims-events \
     --namespace-name gainwell-integration-prod \
     --resource-group integration-rg \
     --partition-count 10 \
     --message-retention 7
   ```

2. **Implement Outbound Adapter**:
   ```csharp
   public class OutboundEventAdapter : BackgroundService
   {
       private readonly IConsumer<string, InternalEvent> _consumer;
       private readonly IPartnerRegistry _partners;

       protected override async Task ExecuteAsync(CancellationToken stoppingToken)
       {
           // Subscribe to internal events
           _consumer.Subscribe(new[] { "claims-events", "eligibility-events", "provider-events" });

           while (!stoppingToken.IsCancellationRequested)
           {
               var consumeResult = _consumer.Consume(stoppingToken);
               var internalEvent = consumeResult.Message.Value;

               // Find partners interested in this event type
               var partners = await _partners.GetSubscribedPartnersAsync(internalEvent.EventType);

               foreach (var partner in partners)
               {
                   try
                   {
                       // Transform to partner format
                       var externalEvent = await TransformEventAsync(internalEvent, partner);

                       // Deliver via partner's protocol
                       await DeliverEventAsync(externalEvent, partner);
                   }
                   catch (Exception ex)
                   {
                       _logger.LogError(ex, "Failed to deliver event {EventId} to partner {Partner}",
                           internalEvent.EventId, partner.Id);
                       // Event moves to retry queue
                   }
               }

               _consumer.Commit(consumeResult);
           }
       }
   }
   ```

3. **Create Partner Registry Schema**:
   ```sql
   CREATE TABLE Partners (
       PartnerId UNIQUEIDENTIFIER PRIMARY KEY,
       Name NVARCHAR(200) NOT NULL,
       Type NVARCHAR(50) NOT NULL, -- State, Payer, HIE, Provider, PBM
       Status NVARCHAR(50) NOT NULL, -- Active, Testing, Suspended
       OnboardedDate DATETIME NOT NULL,
       ContractEndDate DATETIME NULL
   );

   CREATE TABLE PartnerEventSubscriptions (
       SubscriptionId UNIQUEIDENTIFIER PRIMARY KEY,
       PartnerId UNIQUEIDENTIFIER NOT NULL,
       EventType NVARCHAR(200) NOT NULL,
       Protocol NVARCHAR(50) NOT NULL, -- Webhook, SFTP, API
       ProtocolConfig NVARCHAR(MAX) NOT NULL, -- JSON config
       IsActive BIT NOT NULL DEFAULT 1,
       FOREIGN KEY (PartnerId) REFERENCES Partners(PartnerId)
   );

   CREATE TABLE EventDeliveryLog (
       LogId BIGINT IDENTITY PRIMARY KEY,
       EventId NVARCHAR(100) NOT NULL,
       PartnerId UNIQUEIDENTIFIER NOT NULL,
       EventType NVARCHAR(200) NOT NULL,
       AttemptedAt DATETIME NOT NULL,
       DeliveredAt DATETIME NULL,
       StatusCode NVARCHAR(50) NULL,
       ErrorMessage NVARCHAR(MAX) NULL,
       RetryCount INT NOT NULL DEFAULT 0
   );
   ```

4. **Implement First Protocol Handler (Webhook)**:
   ```csharp
   public class WebhookProtocolHandler : IProtocolHandler
   {
       public async Task<DeliveryResult> DeliverAsync(ExternalEvent evt, PartnerConfig config)
       {
           var webhookUrl = config.WebhookUrl;
           var authHeader = config.AuthType == "ApiKey"
               ? ("X-API-Key", config.ApiKey)
               : ("Authorization", $"Bearer {await GetOAuthTokenAsync(config)}");

           var request = new HttpRequestMessage(HttpMethod.Post, webhookUrl);
           request.Headers.Add(authHeader.Item1, authHeader.Item2);
           request.Headers.Add("X-Event-Id", evt.EventId);
           request.Headers.Add("X-Event-Type", evt.EventType);
           request.Content = JsonContent.Create(evt.Payload);

           var response = await _httpClient.SendAsync(request);

           return new DeliveryResult
           {
               Success = response.IsSuccessStatusCode,
               StatusCode = (int)response.StatusCode,
               Message = await response.Content.ReadAsStringAsync()
           };
       }
   }
   ```

**Deliverables**:
- Event broker operational with 99.9% availability
- Outbound adapter processing internal events
- Partner Registry with first partner configured
- Webhook protocol handler deployed
- Monitoring dashboards showing event flow

