#### Phase 2: Expansion (Weeks 5-12)

**Goal**: Onboard multiple partners and add protocol handlers

**Activities**:

1. **Add SFTP Protocol Handler**:
   ```csharp
   public class SftpProtocolHandler : IProtocolHandler
   {
       public async Task<DeliveryResult> DeliverAsync(ExternalEvent evt, PartnerConfig config)
       {
           using var sftp = new SftpClient(config.SftpHost, config.SftpUsername, config.SftpPassword);
           sftp.Connect();

           // Generate file in partner format
           var fileName = $"{config.FilePrefix}_{evt.OccurredAt:yyyyMMddHHmmss}_{evt.EventId}.json";
           var fileContent = JsonSerializer.Serialize(evt.Payload);
           var fileBytes = Encoding.UTF8.GetBytes(fileContent);

           // Upload to partner directory
           using var stream = new MemoryStream(fileBytes);
           sftp.UploadFile(stream, $"{config.SftpDirectory}/{fileName}");

           // Generate control file if required
           if (config.RequiresControlFile)
           {
               var controlContent = $"FILENAME={fileName}\nRECORDS=1\nSIZE={fileBytes.Length}\n";
               var controlBytes = Encoding.UTF8.GetBytes(controlContent);
               using var controlStream = new MemoryStream(controlBytes);
               sftp.UploadFile(controlStream, $"{config.SftpDirectory}/{fileName}.ctl");
           }

           sftp.Disconnect();

           return new DeliveryResult { Success = true, Message = $"Uploaded {fileName}" };
       }
   }
   ```

2. **Implement Inbound Adapter for Webhooks**:
   ```csharp
   [ApiController]
   [Route("api/integration/inbound")]
   public class InboundWebhookController : ControllerBase
   {
       private readonly IPartnerRegistry _partners;
       private readonly IEventPublisher _publisher;

       [HttpPost("{partnerId}/events")]
       public async Task<IActionResult> ReceiveEventAsync(
           string partnerId,
           [FromBody] JsonElement payload)
       {
           // Authenticate partner
           var apiKey = Request.Headers["X-API-Key"].FirstOrDefault();
           var partner = await _partners.AuthenticateAsync(partnerId, apiKey);
           if (partner == null)
           {
               return Unauthorized();
           }

           // Rate limit check
           if (await _rateLimiter.IsRateLimitedAsync(partnerId))
           {
               return StatusCode(429, "Rate limit exceeded");
           }

           // Extract event metadata
           var eventType = Request.Headers["X-Event-Type"].FirstOrDefault();
           var eventId = Request.Headers["X-Event-Id"].FirstOrDefault() ?? Guid.NewGuid().ToString();

           // Transform to internal format
           var internalEvent = await TransformExternalEventAsync(payload, partner, eventType);

           // Publish to internal broker
           await _publisher.PublishAsync("external-events", internalEvent);

           // Log for audit
           await _auditLog.LogInboundEventAsync(partnerId, eventId, eventType);

           return Accepted(new { eventId, status = "accepted" });
       }
   }
   ```

3. **Onboard Multiple Partners**:
   - Create partner profiles in Partner Registry
   - Configure event subscriptions (which event types each partner receives)
   - Set up authentication credentials (API keys, OAuth clients, SFTP accounts)
   - Configure rate limits per partner
   - Document partner-specific data mappings

4. **Implement Schema Validation**:
   ```csharp
   public class SchemaValidator
   {
       private readonly ISchemaRegistry _schemaRegistry;

       public async Task<ValidationResult> ValidateAsync(string eventType, JsonElement payload)
       {
           // Retrieve schema for this event type
           var schema = await _schemaRegistry.GetSchemaAsync(eventType);
           if (schema == null)
           {
               return ValidationResult.Failure($"Schema not found for {eventType}");
           }

           // Validate payload against JSON Schema
           var schemaObj = JsonSchema.FromJsonAsync(schema.SchemaJson).Result;
           var validationErrors = schemaObj.Validate(payload.GetRawText());

           if (validationErrors.Any())
           {
               return ValidationResult.Failure(
                   $"Schema validation failed: {string.Join(", ", validationErrors.Select(e => e.Message))}");
           }

           return ValidationResult.Success();
       }
   }
   ```

**Deliverables**:
- 5+ partners onboarded with different protocols
- SFTP and API polling protocols operational
- Inbound adapter receiving external events
- Schema validation enforced for all events
